//! UniFFI bindings of `musette-core`, for the iOS and Android builds of the
//! app (React Native module generated by uniffi-bindgen-react-native in
//! `app/modules/musette-native`). Types only: the logic is in `musette-core`,
//! shared with `musette-wasm`.
//!
//! Names follow `musette-wasm` once converted to camelCase, so that the app
//! wraps both the same way (`app/src/lib/core/`).

use std::sync::Mutex;

uniffi::setup_scaffolding!();

#[derive(Debug, uniffi::Error)]
pub enum FfiError {
    /// The message of `musette_core::Error`.
    Core { message: String },
}

impl std::fmt::Display for FfiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let FfiError::Core { message } = self;
        f.write_str(message)
    }
}

impl From<musette_core::Error> for FfiError {
    fn from(e: musette_core::Error) -> Self {
        FfiError::Core { message: e.0 }
    }
}

type Result<T> = std::result::Result<T, FfiError>;

#[derive(uniffi::Record)]
pub struct Climb {
    pub start_m: f64,
    pub end_m: f64,
    pub gain_m: f64,
    pub avg_grade: f64,
    pub max_grade: f64,
    pub category: String,
}

#[derive(uniffi::Record)]
pub struct RouteAnalysis {
    pub distance_m: f64,
    pub ascent_m: f64,
    pub profile_step_m: f64,
    pub profile: Vec<f64>,
    pub climbs: Vec<Climb>,
    pub simplified: Vec<u32>,
    pub simplified_m: Vec<f64>,
}

/// Analyse a route. `eles` uses NaN for missing elevation.
#[uniffi::export]
pub fn analyze_route(lats: Vec<f64>, lons: Vec<f64>, eles: Vec<f64>) -> Result<RouteAnalysis> {
    let a = musette_core::analyze_route(&lats, &lons, &eles)?;
    Ok(RouteAnalysis {
        distance_m: a.distance_m,
        ascent_m: a.ascent_m,
        profile_step_m: a.profile_step_m,
        profile: a.profile,
        climbs: a
            .climbs
            .into_iter()
            .map(|c| Climb {
                start_m: c.start_m,
                end_m: c.end_m,
                gain_m: c.gain_m,
                avg_grade: c.avg_grade,
                max_grade: c.max_grade,
                category: c.category.to_owned(),
            })
            .collect(),
        simplified: a.simplified,
        simplified_m: a.simplified_m,
    })
}

#[derive(uniffi::Record)]
pub struct ParsedRoute {
    pub name: String,
    pub lats: Vec<f64>,
    pub lons: Vec<f64>,
    pub eles: Vec<f64>,
}

/// Read a GPX file; the error is `noPoints` or `badPoint`.
#[uniffi::export]
pub fn parse_gpx(text: String) -> Result<ParsedRoute> {
    let r = musette_core::parse_gpx(&text)?;
    Ok(ParsedRoute {
        name: r.name,
        lats: r.lats,
        lons: r.lons,
        eles: r.eles,
    })
}

/// The CC600 background map of a route (`musette_core::cc600_build_map`).
#[uniffi::export]
#[allow(clippy::too_many_arguments)]
pub fn cc600_build_map(
    name: String,
    lats: Vec<f64>,
    lons: Vec<f64>,
    eles: Vec<f64>,
    classes: Vec<String>,
    lengths: Vec<u32>,
    feature_lats: Vec<f64>,
    feature_lons: Vec<f64>,
    corridor_m: f64,
) -> Result<Vec<u8>> {
    let route = musette_core::ParsedRoute {
        name,
        lats,
        lons,
        eles,
    };
    Ok(musette_core::cc600_build_map(
        &route,
        &classes,
        &lengths,
        &feature_lats,
        &feature_lons,
        corridor_m,
    )?)
}

/// Fails if the FIT file is truncated or corrupted.
#[uniffi::export]
pub fn verify_fit(bytes: Vec<u8>) -> Result<u32> {
    Ok(musette_core::verify_fit(&bytes)?)
}

#[derive(uniffi::Record)]
pub struct ActivityRef {
    pub id: String,
    pub size: Option<u64>,
}

/// Pick activity files from a Bryton drive listing.
#[uniffi::export]
pub fn bryton_find_activities(paths: Vec<String>, sizes: Vec<f64>) -> Vec<ActivityRef> {
    musette_core::bryton_find_activities(paths, &sizes)
        .into_iter()
        .map(|a| ActivityRef {
            id: a.id,
            size: a.size,
        })
        .collect()
}

#[derive(uniffi::Record)]
pub struct Capabilities {
    pub download_activities: bool,
    pub upload_route: bool,
    pub route_corridor_map: bool,
    pub climbs_on_device: bool,
    pub settings: bool,
    pub sensors: bool,
    pub wifi_sync: bool,
}

/// What a model can do over a link (`ble` or `usbFiles`).
#[uniffi::export]
pub fn capabilities(model: String, link: String) -> Result<Capabilities> {
    let link = match link.as_str() {
        "ble" => musette_core::Link::Ble,
        "usbFiles" => musette_core::Link::UsbFiles,
        _ => return Err(musette_core::Error(format!("unknown link {link}")).into()),
    };
    let c = musette_core::capabilities(musette_core::model(&model)?, link);
    Ok(Capabilities {
        download_activities: c.download_activities,
        upload_route: c.upload_route,
        route_corridor_map: c.route_corridor_map,
        climbs_on_device: c.climbs_on_device,
        settings: c.settings,
        sensors: c.sensors,
        wifi_sync: c.wifi_sync,
    })
}

#[derive(uniffi::Record)]
pub struct SettingField {
    pub key: String,
    /// `bool`, `number`, `choice` or `text`.
    pub kind: String,
    pub min: Option<f64>,
    pub max: Option<f64>,
    pub options: Vec<String>,
    pub labels: Vec<String>,
    pub writable: bool,
}

impl From<musette_core::SettingField> for SettingField {
    fn from(f: musette_core::SettingField) -> Self {
        Self {
            key: f.key,
            kind: f.kind.to_owned(),
            min: f.min,
            max: f.max,
            options: f.options,
            labels: f.labels,
            writable: f.writable,
        }
    }
}

/// The settings of a model and what each takes.
#[uniffi::export]
pub fn setting_fields(model: String) -> Result<Vec<SettingField>> {
    let model = musette_core::model(&model)?;
    Ok(musette_core::setting_fields(model)
        .into_iter()
        .map(Into::into)
        .collect())
}

#[derive(uniffi::Record)]
pub struct Setting {
    pub key: String,
    pub number: Option<f64>,
    pub text: String,
}

#[derive(uniffi::Record)]
pub struct Channel {
    pub service: String,
    pub characteristic: String,
    pub with_response: bool,
    pub split: bool,
}

#[derive(uniffi::Record)]
pub struct Write {
    pub channel: u8,
    pub bytes: Vec<u8>,
}

#[derive(uniffi::Record)]
pub struct Activity {
    pub id: String,
    pub start_time: Option<i64>,
    pub local_time: bool,
    pub size: Option<u64>,
    pub synced: Option<bool>,
}

/// `musette_core::Outcome` in one record: `kind` (`done`, `info`,
/// `activities`, `file`, `settings`, `failed`) says which fields count.
#[derive(uniffi::Record)]
pub struct Outcome {
    pub kind: String,
    pub name: String,
    pub recording: bool,
    pub route_max: Option<u32>,
    pub map_max: Option<u32>,
    pub free: Option<u32>,
    pub activities: Vec<Activity>,
    pub bytes: Vec<u8>,
    pub fields: Vec<SettingField>,
    pub values: Vec<Setting>,
    pub code: String,
    pub detail: String,
}

#[derive(uniffi::Record)]
pub struct Step {
    pub subscribe: Vec<u8>,
    pub writes: Vec<Write>,
    pub progress: Option<f64>,
    pub wait_ms: Option<u32>,
    pub outcome: Option<Outcome>,
}

fn outcome(o: musette_core::Outcome) -> Outcome {
    use musette_core::Outcome as O;
    let mut out = Outcome {
        kind: String::new(),
        name: String::new(),
        recording: false,
        route_max: None,
        map_max: None,
        free: None,
        activities: vec![],
        bytes: vec![],
        fields: vec![],
        values: vec![],
        code: String::new(),
        detail: String::new(),
    };
    out.kind = match o {
        O::Done => "done",
        O::Info {
            name,
            recording,
            route_max,
            map_max,
            free,
        } => {
            out.name = name;
            out.recording = recording;
            out.route_max = route_max;
            out.map_max = map_max;
            out.free = free;
            "info"
        }
        O::Activities { activities } => {
            out.activities = activities
                .into_iter()
                .map(|a| Activity {
                    id: a.id,
                    start_time: a.start_time,
                    local_time: a.local_time,
                    size: a.size,
                    synced: a.synced,
                })
                .collect();
            "activities"
        }
        O::File { bytes } => {
            out.bytes = bytes;
            "file"
        }
        O::Settings { fields, values } => {
            out.fields = fields.into_iter().map(Into::into).collect();
            out.values = values
                .into_iter()
                .map(|v| Setting {
                    key: v.key,
                    number: v.number,
                    text: v.text,
                })
                .collect();
            "settings"
        }
        O::Failed(f) => {
            out.code = f.code.to_owned();
            out.detail = f.detail;
            "failed"
        }
    }
    .to_owned();
    out
}

impl From<musette_core::Step> for Step {
    fn from(s: musette_core::Step) -> Self {
        Self {
            subscribe: s.subscribe,
            writes: s
                .writes
                .into_iter()
                .map(|w| Write {
                    channel: w.channel,
                    bytes: w.bytes,
                })
                .collect(),
            progress: s.progress,
            wait_ms: s.wait_ms,
            outcome: s.outcome.map(outcome),
        }
    }
}

/// One connection to a device (`musette_core::Session`).
#[derive(uniffi::Object)]
pub struct Session(Mutex<musette_core::Session>);

#[uniffi::export]
impl Session {
    /// The model's own timing, unless given (tests).
    #[uniffi::constructor]
    pub fn new(model: String, request_ms: Option<u32>, short_ms: Option<u32>) -> Result<Self> {
        let model = musette_core::model(&model)?;
        let t = musette_core::Timing::of(model);
        let timing = musette_core::Timing {
            request_ms: request_ms.unwrap_or(t.request_ms),
            short_ms: short_ms.unwrap_or(t.short_ms),
        };
        Ok(Self(Mutex::new(musette_core::Session::new(model, timing))))
    }

    pub fn channels(&self) -> Vec<Channel> {
        self.0
            .lock()
            .unwrap()
            .channels()
            .into_iter()
            .map(|c| Channel {
                service: c.service.to_owned(),
                characteristic: c.characteristic.to_owned(),
                with_response: c.with_response,
                split: c.split,
            })
            .collect()
    }

    pub fn connect(&self) -> Result<Step> {
        Ok(self.0.lock().unwrap().connect()?.into())
    }

    pub fn list_activities(&self) -> Result<Step> {
        Ok(self.0.lock().unwrap().list_activities()?.into())
    }

    pub fn download(&self, id: String, size: Option<u64>) -> Result<Step> {
        Ok(self.0.lock().unwrap().download(&id, size)?.into())
    }

    pub fn acknowledge(&self, id: String) -> Result<Step> {
        Ok(self.0.lock().unwrap().acknowledge(&id)?.into())
    }

    /// `eles` uses NaN for missing elevation.
    pub fn send_route(
        &self,
        name: String,
        lats: Vec<f64>,
        lons: Vec<f64>,
        eles: Vec<f64>,
    ) -> Result<Step> {
        let route = musette_core::ParsedRoute {
            name,
            lats,
            lons,
            eles,
        };
        Ok(self.0.lock().unwrap().send_route(&route)?.into())
    }

    /// `kind`: `route` or `map`.
    pub fn send_file(&self, kind: String, bytes: Vec<u8>) -> Result<Step> {
        let kind = match kind.as_str() {
            "route" => musette_core::FileKind::Route,
            "map" => musette_core::FileKind::Map,
            _ => return Err(musette_core::Error(format!("unknown file kind {kind}")).into()),
        };
        Ok(self.0.lock().unwrap().send_file(kind, bytes)?.into())
    }

    pub fn device_info(&self) -> Result<Step> {
        Ok(self.0.lock().unwrap().device_info()?.into())
    }

    pub fn read_settings(&self) -> Result<Step> {
        Ok(self.0.lock().unwrap().read_settings()?.into())
    }

    pub fn write_settings(&self, changes: Vec<Setting>) -> Result<Step> {
        let changes: Vec<musette_core::Setting> = changes
            .into_iter()
            .map(|c| musette_core::Setting {
                key: c.key,
                number: c.number,
                text: c.text,
            })
            .collect();
        Ok(self.0.lock().unwrap().write_settings(&changes)?.into())
    }

    pub fn on_notify(&self, channel: u8, bytes: Vec<u8>) -> Step {
        self.0.lock().unwrap().on_notify(channel, &bytes).into()
    }

    pub fn on_timeout(&self) -> Step {
        self.0.lock().unwrap().on_timeout().into()
    }
}

/// A CC600 in memory (demo without a device).
#[derive(uniffi::Object)]
pub struct Cc600Simulator(Mutex<musette_core::Cc600Simulator>);

#[uniffi::export]
impl Cc600Simulator {
    #[uniffi::constructor]
    pub fn new(
        window: u16,
        free: u32,
        settings: String,
        lose_chunks: Vec<u32>,
        lose_acks: Vec<u32>,
    ) -> Self {
        Self(Mutex::new(musette_core::Cc600Simulator::new(
            window,
            free,
            settings,
            lose_chunks,
            lose_acks,
        )))
    }

    /// `start_time` in Unix seconds.
    pub fn add_activity(&self, id: u32, start_time: i64, fit: Vec<u8>) {
        self.0.lock().unwrap().add_activity(id, start_time, fit);
    }

    /// The frames the device answers.
    pub fn write(&self, bytes: Vec<u8>) -> Vec<Vec<u8>> {
        self.0.lock().unwrap().write(&bytes)
    }

    pub fn disconnect(&self) {
        self.0.lock().unwrap().disconnect();
    }

    pub fn received(&self) -> u32 {
        self.0.lock().unwrap().received()
    }

    pub fn committed(&self) -> Option<Vec<u8>> {
        self.0.lock().unwrap().committed()
    }

    pub fn chunk_bytes(&self) -> u32 {
        self.0.lock().unwrap().chunk_bytes()
    }

    pub fn acked(&self) -> Vec<u32> {
        self.0.lock().unwrap().acked()
    }

    pub fn settings(&self) -> String {
        self.0.lock().unwrap().settings()
    }

    pub fn settings_writes(&self) -> Vec<String> {
        self.0.lock().unwrap().settings_writes()
    }
}
